@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>

@{
    Layout = null;
}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta http-equiv="X-UA-Compatible" content="IE=edge,chrome=1">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>@Model.Title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true">
</head>
<body class="bg-gray-50 text-gray-900">
    <div class="container mx-auto px-4 py-8">
        <header class="mb-12">
            <h1 class="text-4xl font-bold text-blue-600 mb-4">@Model.Title</h1>
        </header>

        <main>
            @if (!string.IsNullOrEmpty(Model.Intro))
            {
                <div class="prose prose-lg max-w-none mb-12">
                    @await Html.GetBlockGridHtmlAsync(Model, "body")
                </div>
            }

            <section class="mb-12">
                <h2 class="text-2xl font-semibold text-gray-800 mb-6">Recent Posts</h2>
                <div class="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
                    @foreach (var post in Model.Children<BlogPost>()) {
                        <article class="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow">
                            @if (post.ListingImage != null)
                            {
                                <img src="@Umbraco.Cms.Web.Common.Umbraco.Cms.Web.Common.Controllers.ContentController.GetCropUrl(post.ListingImage, "blogListing")"
                                     alt="@post.Title" class="w-full h-48 object-cover">
                            }
                            <div class="p-6">
                                <h3 class="text-xl font-bold text-blue-700 mb-2">
                                    <a href="@post.Url()" class="hover:text-blue-900">@post.Title</a>
                                </h3>
                                <p class="text-gray-600 text-sm mb-2">
                                    @post.PublishDate.ToString("MMMM dd, yyyy")
                                </p>
                                @if (!string.IsNullOrEmpty(post.Excerpt))
                                {
                                    <p class="text-gray-700 mb-4">@post.Excerpt</p>
                                }
                                <a href="@post.Url()" class="inline-block bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors">Read More</a>
                            </div>
                        </article>
                    }
                </div>
            </section>
        </main>

        <footer class="mt-16 pt-8 border-t border-gray-200 text-center text-gray-500">
            <p>&copy; @DateTime.Now.Year - MCP Blog</p>
        </footer>
    </div>
</body>
</html>

