@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models

@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>

@{
    var image = Model.Content.Image;
    var caption = Model.Content.Caption;
}

@if (image != null)
{
    <div class="image-block my-6 text-center">
        <img src="@Umbraco.Cms.Web.Common.Umbraco.Cms.Web.Common.Controllers.ContentController.GetCropUrl(image, "blogContent")"
             alt="@caption"
             class="max-w-full h-auto mx-auto rounded-lg shadow-md">
        @if (!string.IsNullOrEmpty(caption))
        {
            <p class="mt-2 text-sm text-gray-600 italic">@caption</p>
        }
    </div>
}

