@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models

@inherits UmbracoViewPage<BlockGridItem<QuoteBlock>>

@{
    var quote = Model.Content.Quote;
    var attribution = Model.Content.Attribution;
}

@if (!string.IsNullOrEmpty(quote))
{
    <blockquote class="quote-block my-6 border-l-4 border-blue-500 pl-4 italic text-gray-700">
        <p class="text-lg">@quote</p>
        @if (!string.IsNullOrEmpty(attribution))
        {
            <footer class="mt-2 text-sm text-gray-500 not-italic">— @attribution</footer>
        }
    </blockquote>
}

